baseCss:
/* Engine base: frame, ground, chrome and editor states. No visual-language values here. */
.deck .slide {
  position: relative;
  box-sizing: border-box;
  width: var(--frame-w);
  height: var(--frame-h);
  overflow: hidden;
  background: var(--slide-bg);
  color: var(--slide-ink);
  container: slide / size;
}
.deck .slide *,
.deck .slide *::before,
.deck .slide *::after { box-sizing: border-box; }
.deck .slide :where(h1, h2, h3, p, ol, ul, figure, blockquote, table) { margin: 0; padding: 0; }
.deck .slide :where(ol, ul) { list-style: none; }
.deck .slide :where(h1, h2, h3) { text-wrap: balance; }
.deck .slide :where(p, li) { text-wrap: pretty; }
.deck .slide [data-nowrap] { white-space: nowrap; }
/* rich subset: *muted* and ==highlight== — VLs restyle these */
.deck .slide em { font-style: normal; opacity: 0.5; }
.deck .slide mark { background: none; color: var(--color-emphasis); }
.deck .slide [data-region] { min-height: 0; min-width: 0; }

.deck [data-decor] { pointer-events: none; }
.deck [data-decor]:empty { display: none; }
.deck [data-decor] svg { display: block; width: 100%; height: 100%; }

.deck .chrome { position: absolute; z-index: 2; opacity: 0.7; }
.deck .chrome--top { top: calc(var(--space-frame-y) * 0.4); left: var(--space-frame-x); }
.deck .chrome--bottom { bottom: calc(var(--space-frame-y) * 0.4); right: var(--space-frame-x); }

/* edit-mode affordances */
.deck.is-editing :is([data-slot-type="text"], [data-slot-type="rich"]):hover { outline: 2px dashed color-mix(in srgb, currentColor 35%, transparent); outline-offset: 6px; }
.deck.is-editing [contenteditable] { outline: 2px solid #3b82f6; outline-offset: 6px; cursor: text; }
.deck.is-editing [data-overflow] { outline: 3px solid #f59e0b !important; outline-offset: 4px; }

variants.css:
.a-bullets.v-big-numerals {
  display: grid;
  grid-template-columns: minmax(0, 4fr) minmax(0, 8fr);
  grid-template-rows: minmax(0, 1fr);
  padding: calc(var(--space-frame-y) * 1.3) var(--space-frame-x) var(--space-frame-y);
  column-gap: calc(var(--space-gutter) * 1.6);
}
.a-bullets.v-big-numerals .bn-card { position: relative; overflow: hidden; border-radius: var(--radius-image); min-height: 0; }
.a-bullets.v-big-numerals .bn-img,
.a-bullets.v-big-numerals .bn-placeholder { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.a-bullets.v-big-numerals .bn-placeholder:empty { display: block; background: color-mix(in srgb, currentColor 10%, transparent); }
.a-bullets.v-big-numerals .bn-caption {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  display: grid;
  gap: 0.3em;
  padding: var(--space-gutter);
  background: linear-gradient(to top, color-mix(in srgb, var(--color-ground-inverse) 75%, transparent), transparent);
  color: var(--color-ink-on-inverse);
}
.a-bullets.v-big-numerals .bn-right { display: grid; grid-template-rows: auto minmax(0, 1fr); gap: var(--space-gutter); min-height: 0; }
.a-bullets.v-big-numerals .bn-items { display: grid; grid-auto-rows: minmax(0, 1fr); counter-reset: bn; overflow: hidden; }
.a-bullets.v-big-numerals .bn-item {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) minmax(0, 1.2fr);
  align-items: center;
  column-gap: var(--space-gutter);
  border-top: var(--line-hair) solid var(--color-line);
  counter-increment: bn;
  min-height: 0;
}
/* fixed numeral column (in the numeral's own em) so every row's title lines up */
.a-bullets.v-big-numerals .bn-num { font-size: min(var(--t-display-0-size), 22cqh); width: 0.7em; text-align: center; line-height: 1; color: var(--color-emphasis); }
.a-bullets.v-big-numerals .bn-num::before { content: counter(bn); }
.a-bullets.v-big-numerals .bn-text { opacity: 0.7; }

.a-bullets.v-cards-grid {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  padding: calc(var(--space-frame-y) * 1.5) var(--space-frame-x) var(--space-frame-y);
  row-gap: var(--space-section);
}
.a-bullets.v-cards-grid .cg-head { display: grid; gap: var(--space-tight); max-width: 70%; }
.a-bullets.v-cards-grid .cg-items {
  --cols: 3;
  display: grid;
  grid-template-columns: repeat(var(--cols), minmax(0, 1fr));
  grid-auto-rows: minmax(0, 1fr);
  gap: var(--space-gutter);
  overflow: hidden;
}
.a-bullets.v-cards-grid .cg-items[data-count="2"],
.a-bullets.v-cards-grid .cg-items[data-count="4"] { --cols: 2; }
.a-bullets.v-cards-grid .cg-card {
  display: flex;
  flex-direction: column;
  gap: var(--space-tight);
  padding: var(--space-gutter);
  background: var(--color-surface-card, transparent);
  border: var(--line-hair) solid var(--color-line);
  border-radius: var(--radius-card);
  overflow: hidden;
}
@container slide (aspect-ratio < 1) {
  .a-bullets.v-cards-grid .cg-items { --cols: 2; }
  .a-bullets.v-cards-grid .cg-head { max-width: none; }
}

/* columns separated by hairlines; each column alternates an illustration and a numeral tile */
.a-bullets.v-contents-tiles { display: grid; grid-template-rows: minmax(0, 1fr) auto; padding: 0; }
.a-bullets.v-contents-tiles .ct-cols { display: grid; grid-template-columns: repeat(var(--item-count), minmax(0, 1fr)); counter-reset: ct; overflow: hidden; }
.a-bullets.v-contents-tiles .ct-col { display: grid; grid-template-rows: minmax(0, 1fr) auto minmax(0, 1fr); border-right: var(--line-hair) solid currentColor; counter-increment: ct; min-width: 0; }
.a-bullets.v-contents-tiles .ct-col:last-child { border-right: 0; }
.a-bullets.v-contents-tiles .ct-col:nth-child(even) .ct-cell--art { order: 3; }
.a-bullets.v-contents-tiles .ct-col:nth-child(even) .ct-cell--num { order: 1; }
.a-bullets.v-contents-tiles .ct-col:nth-child(even) .ct-label { order: 2; }
.a-bullets.v-contents-tiles .ct-cell { position: relative; display: grid; place-items: center; padding: 8%; min-height: 0; }
.a-bullets.v-contents-tiles .ct-cell--art .il-art { width: 100%; height: 100%; }
.a-bullets.v-contents-tiles .ct-cell--art .il-art svg { width: 100%; height: 100%; display: block; }
/* sized to the cell on both axes so narrow columns (5–6 items) shrink the tile instead of spilling */
.a-bullets.v-contents-tiles .ct-cell--num { container-type: size; }
.a-bullets.v-contents-tiles .ct-tile { display: grid; place-items: center; height: min(82cqh, 125cqw); aspect-ratio: 4 / 5; border-radius: 18%; background: currentColor; }
.a-bullets.v-contents-tiles .ct-tile::before { content: counter(ct); color: var(--slide-bg); font-family: var(--font-text); font-size: var(--t-display-1-size); font-weight: 300; line-height: 1; }
.a-bullets.v-contents-tiles .ct-label { display: grid; justify-items: center; text-align: center; gap: 0.2em; margin: 0 8%; padding: var(--space-tight) 0; border-top: var(--line-hair) solid currentColor; border-bottom: var(--line-hair) solid currentColor; }
.a-bullets.v-contents-tiles .ct-hidden-title { display: none; }

.a-bullets.v-glass-stack {
  display: grid;
  grid-template-columns: minmax(0, 5fr) minmax(0, 6fr);
  grid-template-rows: minmax(0, 1fr);
  padding: var(--space-frame-y) var(--space-frame-x);
  column-gap: calc(var(--space-gutter) * 2.5);
}
.a-bullets.v-glass-stack .gk-left { display: flex; flex-direction: column; gap: var(--space-gutter); overflow: hidden; }
.a-bullets.v-glass-stack .gk-intro { margin-top: auto; max-width: 30em; opacity: 0.75; }
.a-bullets.v-glass-stack .gk-items { display: grid; grid-auto-rows: minmax(0, auto); align-content: center; gap: var(--space-gutter); counter-reset: gk; overflow: hidden; }
.a-bullets.v-glass-stack .gk-card {
  position: relative;
  display: grid;
  gap: var(--space-tight);
  padding: var(--space-gutter) calc(var(--space-gutter) * 3) var(--space-gutter) var(--space-gutter);
  border: var(--line-hair) solid var(--color-line);
  border-radius: var(--radius-card);
  background: var(--color-surface-card, transparent);
  counter-increment: gk;
}
.a-bullets.v-glass-stack .gk-tag { position: absolute; top: var(--space-gutter); right: var(--space-gutter); opacity: 0.7; }
.a-bullets.v-glass-stack .gk-tag::before { content: "(" counter(gk, decimal-leading-zero) ")"; }
.a-bullets.v-glass-stack .gk-text { opacity: 0.7; }
.a-bullets.v-glass-stack .is-emphasis { background: var(--color-surface-highlight, var(--color-ink-on-inverse)); color: var(--color-ink-on-highlight, var(--color-ground-inverse)); border-color: transparent; }

/* rows of icon + label separated by hairlines; first and last rows fade out like a scrolling list */
.a-bullets.v-icon-rows {
  display: grid;
  grid-template-columns: minmax(0, 4fr) minmax(0, 6fr);
  grid-template-rows: minmax(0, 1fr);
  padding: var(--space-frame-y) var(--space-frame-x);
  column-gap: calc(var(--space-gutter) * 2);
}
.a-bullets.v-icon-rows .ir-left { display: flex; flex-direction: column; gap: var(--space-gutter); overflow: hidden; }
.a-bullets.v-icon-rows .ir-intro { margin-top: auto; max-width: 26em; opacity: 0.7; }
.a-bullets.v-icon-rows .ir-rows {
  display: grid;
  grid-auto-rows: minmax(0, 1fr);
  overflow: hidden;
  border-left: var(--line-hair) solid var(--color-line);
  -webkit-mask-image: linear-gradient(to bottom, rgb(0 0 0 / 0.35), #000 18%, #000 82%, rgb(0 0 0 / 0.35));
  mask-image: linear-gradient(to bottom, rgb(0 0 0 / 0.35), #000 18%, #000 82%, rgb(0 0 0 / 0.35));
}
.a-bullets.v-icon-rows .ir-row {
  display: grid;
  grid-template-columns: 56px minmax(0, 1fr);
  align-items: center;
  column-gap: var(--space-gutter);
  padding: 0 var(--space-gutter);
  border-bottom: var(--line-hair) solid var(--color-line);
  min-height: 0;
}
.a-bullets.v-icon-rows .ir-row:last-child { border-bottom: 0; }
.a-bullets.v-icon-rows .ir-icon { width: 48px; height: 48px; }
.a-bullets.v-icon-rows .ir-icon:empty { display: block; border: var(--line-hair) solid var(--color-line); border-radius: 8px; }
.a-bullets.v-icon-rows .ir-name { display: grid; gap: 0.2em; }
.a-bullets.v-icon-rows .ir-text { opacity: 0.6; }

.a-bullets.v-leader-orbit {
  display: grid;
  grid-template-columns: minmax(0, 4fr) minmax(0, 8fr);
  grid-template-rows: minmax(0, 1fr);
  padding: calc(var(--space-frame-y) * 1.4) 0 var(--space-frame-y) var(--space-frame-x);
  column-gap: var(--space-gutter);
}
.a-bullets.v-leader-orbit .lo-head { display: grid; align-content: start; gap: var(--space-gutter); max-width: 92%; overflow: hidden; }
.a-bullets.v-leader-orbit .lo-intro { max-width: 22em; }
/* labels stagger left/right; each leader line runs to the slide edge, where the orbit (if the VL draws one) covers it */
.a-bullets.v-leader-orbit .lo-items { display: grid; grid-auto-rows: minmax(0, 1fr); align-content: space-evenly; counter-reset: lo; overflow: hidden; }
.a-bullets.v-leader-orbit .lo-item { --indent: 0%; display: flex; align-items: center; padding-left: var(--indent); counter-increment: lo; min-height: 0; }
.a-bullets.v-leader-orbit .lo-item:nth-child(7n + 1) { --indent: 28%; }
.a-bullets.v-leader-orbit .lo-item:nth-child(7n + 2) { --indent: 4%; }
.a-bullets.v-leader-orbit .lo-item:nth-child(7n + 3) { --indent: 36%; }
.a-bullets.v-leader-orbit .lo-item:nth-child(7n + 4) { --indent: 18%; }
.a-bullets.v-leader-orbit .lo-item:nth-child(7n + 5) { --indent: 36%; }
.a-bullets.v-leader-orbit .lo-item:nth-child(7n + 6) { --indent: 2%; }
.a-bullets.v-leader-orbit .lo-item:nth-child(7n + 7) { --indent: 28%; }
.a-bullets.v-leader-orbit .lo-label { display: flex; gap: 0.5em; max-width: 15em; flex-shrink: 0; }
.a-bullets.v-leader-orbit .lo-index::before { content: counter(lo) "."; }
.a-bullets.v-leader-orbit .lo-name { display: grid; }
.a-bullets.v-leader-orbit .lo-line { flex: 1; height: var(--line-hair); margin-left: var(--space-gutter); background: var(--color-line); min-width: 40px; }
.a-bullets.v-leader-orbit .lo-orbit {
  position: absolute;
  z-index: 2;
  top: 50%;
  right: -66cqh;
  height: 116cqh;
  aspect-ratio: 1;
  transform: translateY(-50%);
  pointer-events: none;
}

.a-bullets.v-ledger-photo { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 6fr); grid-template-rows: auto minmax(0, 1fr); padding: calc(var(--space-frame-y) * 1.1) var(--space-frame-x) var(--space-frame-y) calc(var(--space-frame-x) * 0.4); column-gap: calc(var(--space-gutter) * 2.5); row-gap: var(--space-gutter); }
.a-bullets.v-ledger-photo .lp-word { grid-column: 1 / -1; overflow: hidden; padding-left: calc(var(--space-frame-x) * 0.6); }
.a-bullets.v-ledger-photo .lp-title { display: block; max-width: 100%; overflow: hidden; line-height: 0.86; }
.a-bullets.v-ledger-photo .lp-photo { position: relative; overflow: hidden; }
.a-bullets.v-ledger-photo .lp-photo :is(img, .ph) { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.a-bullets.v-ledger-photo .lp-right { display: flex; flex-direction: column; justify-content: space-between; gap: var(--space-gutter); overflow: hidden; }
.a-bullets.v-ledger-photo .lp-intro { max-width: 30em; }
.a-bullets.v-ledger-photo .lp-items { display: grid; gap: 0.5em; max-width: 30em; }
.a-bullets.v-ledger-photo .lp-item { display: flex; justify-content: space-between; gap: var(--space-gutter); }
.a-bullets.v-ledger-photo .lp-item.is-emphasis { margin-top: var(--space-section); }
.a-bullets.v-ledger-photo .lp-item.is-emphasis .lp-price { font-size: var(--t-display-3-size); font-family: var(--font-display); font-weight: 600; letter-spacing: -0.02em; }

.a-bullets.v-list {
  display: grid;
  grid-template-columns: minmax(0, 4fr) minmax(0, 7fr);
  grid-template-rows: minmax(0, 1fr);
  padding: calc(var(--space-frame-y) * 1.5) var(--space-frame-x) var(--space-frame-y);
  column-gap: calc(var(--space-gutter) * 2);
  align-items: start;
}
.a-bullets.v-list .bl-head { display: grid; gap: var(--space-gutter); }
.a-bullets.v-list .bl-items { display: grid; align-content: start; max-height: 100%; overflow: hidden; counter-reset: bl; }
.a-bullets.v-list .bl-item {
  display: grid;
  grid-template-columns: 3em minmax(0, 1fr);
  column-gap: var(--space-gutter);
  row-gap: calc(var(--space-tight) / 2);
  padding: var(--space-tight) 0;
  border-top: var(--line-hair) solid var(--color-line);
  counter-increment: bl;
}
.a-bullets.v-list .bl-index { grid-row: span 2; padding-top: 0.4em; }
.a-bullets.v-list .bl-index::before { content: counter(bl, decimal-leading-zero); }
.a-bullets.v-list .bl-text { grid-column: 2; }
.a-bullets.v-list .bl-item { grid-template-columns: 3em minmax(0, 1fr) auto; }
.a-bullets.v-list .bl-tag { grid-column: 3; grid-row: 1; align-self: center; white-space: nowrap; }
.a-bullets.v-list [data-count="7"] .bl-item,
.a-bullets.v-list [data-count="8"] .bl-item { padding: calc(var(--space-tight) / 2) 0; }
@container slide (aspect-ratio < 1) {
  .a-bullets.v-list { grid-template-columns: 1fr; grid-template-rows: auto minmax(0, 1fr); row-gap: var(--space-section); }
}

/* agenda/contents: big numerals in a dark panel that overlaps the slide's lower-right */
.a-bullets.v-numbered-grid {
  display: grid;
  grid-template-columns: minmax(0, 3fr) minmax(0, 8fr);
  grid-template-rows: minmax(0, 1fr);
  padding: calc(var(--space-frame-y) * 1.3) 0 0 var(--space-frame-x);
  column-gap: var(--space-gutter);
}
.a-bullets.v-numbered-grid .ng-head { display: grid; align-content: start; gap: var(--space-gutter); padding-right: var(--space-gutter); }
.a-bullets.v-numbered-grid .ng-panel {
  align-self: end;
  height: 82%;
  padding: calc(var(--space-gutter) * 1.4) var(--space-frame-x) var(--space-frame-y) calc(var(--space-gutter) * 1.4);
  background: var(--color-ground-inverse);
  color: var(--color-ink-on-inverse);
  border-top-left-radius: var(--radius-card);
}
.a-bullets.v-numbered-grid .ng-items {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-auto-rows: minmax(0, 1fr);
  gap: var(--space-gutter) calc(var(--space-gutter) * 1.4);
  height: 100%;
  counter-reset: ng;
  overflow: hidden;
}
.a-bullets.v-numbered-grid .ng-items[data-count="4"] { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.a-bullets.v-numbered-grid .ng-item { display: flex; flex-direction: column; gap: calc(var(--space-tight) * 0.6); counter-increment: ng; min-width: 0; }
.a-bullets.v-numbered-grid .ng-num::before { content: counter(ng, decimal-leading-zero); }
.a-bullets.v-numbered-grid .ng-num { color: var(--color-emphasis); line-height: 1; margin-bottom: var(--space-tight); }
.a-bullets.v-numbered-grid .ng-text { opacity: 0.65; }
.a-bullets.v-numbered-grid .ng-tag { align-self: flex-start; margin-top: auto; padding: 0.2em 0.7em; border-radius: var(--radius-pill); background: var(--color-emphasis); color: var(--color-ink-on-emphasis, #fff); white-space: nowrap; }

.a-bullets.v-photo-outcomes { display: grid; grid-template-columns: minmax(0, 6fr) minmax(0, 5fr); grid-template-rows: minmax(0, 1fr) auto; column-gap: calc(var(--space-gutter) * 2); row-gap: var(--space-gutter); padding: var(--space-frame-y) var(--space-frame-x); }
.a-bullets.v-photo-outcomes .po-photo { grid-column: 1; grid-row: 1; }
.a-bullets.v-photo-outcomes .po-photo { position: relative; overflow: hidden; }
.a-bullets.v-photo-outcomes .po-photo :is(img, .ph) { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.a-bullets.v-photo-outcomes .po-titlecell { grid-column: 1; grid-row: 2; display: grid; gap: var(--space-tight); }
.a-bullets.v-photo-outcomes .po-items { grid-column: 2; grid-row: 1 / span 2; display: grid; grid-template-columns: 1fr 1fr; align-content: center; gap: var(--space-section) var(--space-gutter); overflow: hidden; }
.a-bullets.v-photo-outcomes .po-item { display: grid; gap: 0.4em; }
.a-bullets.v-photo-outcomes .po-text { text-transform: none; letter-spacing: 0; opacity: 0.85; }

/* split ground: left half paints the inverse role, right half keeps the slide's own ground */
.a-bullets.v-split-ledger {
  display: grid;
  grid-template-columns: minmax(0, 5fr) minmax(0, 7fr);
  grid-template-rows: minmax(0, 1fr);
}
.a-bullets.v-split-ledger .sl-left {
  display: flex;
  flex-direction: column;
  gap: var(--space-gutter);
  padding: calc(var(--space-frame-y) * 1.4) calc(var(--space-gutter) * 1.5) var(--space-frame-y) var(--space-frame-x);
  background: var(--color-ground-inverse);
  color: var(--color-ink-on-inverse);
  overflow: hidden;
}
.a-bullets.v-split-ledger .sl-intro { margin-top: auto; max-width: 26em; opacity: 0.75; }
.a-bullets.v-split-ledger .sl-items {
  display: grid;
  grid-auto-rows: minmax(0, 1fr);
  padding: calc(var(--space-frame-y) * 1.4) var(--space-frame-x) var(--space-frame-y) calc(var(--space-gutter) * 1.5);
  counter-reset: sl;
  overflow: hidden;
}
.a-bullets.v-split-ledger .sl-item {
  display: grid;
  grid-template-columns: 2.4em minmax(0, 1fr) minmax(0, 1.3fr);
  column-gap: var(--space-gutter);
  align-items: start;
  padding-top: var(--space-tight);
  border-top: var(--line-hair) solid var(--color-line);
  counter-increment: sl;
  min-height: 0;
}
.a-bullets.v-split-ledger .sl-num::before { content: counter(sl, decimal-leading-zero); }
.a-bullets.v-split-ledger .sl-name { display: grid; justify-items: start; gap: var(--space-tight); }
.a-bullets.v-split-ledger .sl-tag { padding: 0.2em 0.7em; border-radius: var(--radius-pill); border: var(--line-hair) solid var(--color-emphasis); color: var(--color-emphasis); white-space: nowrap; }
.a-bullets.v-split-ledger .sl-text { opacity: 0.75; }

/* left half paints the inverse role with a list of pill rows; the emphasised item gets a feature card on the light right half */
.a-bullets.v-split-rows {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  grid-template-rows: minmax(0, 1fr);
}
.a-bullets.v-split-rows .sr-left {
  display: flex;
  flex-direction: column;
  gap: var(--space-gutter);
  padding: var(--space-frame-y) calc(var(--space-gutter) * 1.5) var(--space-frame-y) var(--space-frame-x);
  background: var(--color-ground-inverse);
  color: var(--color-ink-on-inverse);
  overflow: hidden;
}
.a-bullets.v-split-rows .sr-intro { opacity: 0.7; max-width: 32em; }
.a-bullets.v-split-rows .sr-rows { display: grid; gap: var(--space-tight); margin-top: auto; counter-reset: sr; }
.a-bullets.v-split-rows .sr-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-gutter);
  padding: 0.7em 1em;
  border: var(--line-hair) solid var(--color-line);
  border-radius: var(--radius-card);
  counter-increment: sr;
}
.a-bullets.v-split-rows .sr-tag::before { content: "(" counter(sr, decimal-leading-zero) ")"; }
.a-bullets.v-split-rows .sr-row.is-emphasis { background: var(--color-ink-on-inverse); color: var(--color-ground-inverse); border-color: transparent; }
.a-bullets.v-split-rows .sr-right { position: relative; display: grid; place-items: center; padding: var(--space-frame-y) var(--space-frame-x); overflow: hidden; }
.a-bullets.v-split-rows .sr-panel { position: absolute; inset: 0; }
.a-bullets.v-split-rows .sr-card {
  position: relative;
  width: 82%;
  aspect-ratio: 1.25;
  display: flex;
  flex-direction: column;
