.a-bullets.v-two-column {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  padding: calc(var(--space-frame-y) * 1.4) var(--space-frame-x) var(--space-frame-y);
  row-gap: var(--space-section);
}
.a-bullets.v-two-column .tc2-head { display: grid; gap: var(--space-tight); max-width: 66%; }
.a-bullets.v-two-column .tc2-items {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  grid-auto-flow: column;
  grid-template-rows: repeat(var(--rows, 2), auto);
  align-content: start;
  column-gap: calc(var(--space-gutter) * 2);
  row-gap: var(--space-gutter);
  overflow: hidden;
  counter-reset: tc2;
}
.a-bullets.v-two-column .tc2-items[data-count="5"],
.a-bullets.v-two-column .tc2-items[data-count="6"] { --rows: 3; }
.a-bullets.v-two-column .tc2-items[data-count="7"],
.a-bullets.v-two-column .tc2-items[data-count="8"] { --rows: 4; }
.a-bullets.v-two-column .tc2-item {
  display: grid;
  grid-template-columns: 2.6em minmax(0, 1fr);
  column-gap: var(--space-tight);
  row-gap: calc(var(--space-tight) / 2);
  align-content: start;
  counter-increment: tc2;
}
.a-bullets.v-two-column .tc2-index { grid-row: span 2; padding-top: 0.35em; }
.a-bullets.v-two-column .tc2-index::before { content: counter(tc2, decimal-leading-zero); }
.a-bullets.v-two-column .tc2-text { grid-column: 2; }
@container slide (aspect-ratio < 1) {
  .a-bullets.v-two-column .tc2-items { grid-template-columns: 1fr; grid-auto-flow: row; grid-template-rows: none; }
  .a-bullets.v-two-column .tc2-head { max-width: none; }
}

.a-chart.v-split-panel {
  display: grid;
  grid-template-columns: minmax(0, 4fr) minmax(0, 8fr);
  grid-template-rows: minmax(0, 1fr);
}
.a-chart.v-split-panel .sp-left {
  display: flex;
  flex-direction: column;
  gap: var(--space-gutter);
  padding: var(--space-frame-y) calc(var(--space-gutter) * 1.5) var(--space-frame-y) var(--space-frame-x);
  background: var(--color-ground-inverse);
  color: var(--color-ink-on-inverse);
  overflow: hidden;
}
.a-chart.v-split-panel .sp-foot { margin-top: auto; display: grid; gap: var(--space-tight); opacity: 0.75; }
.a-chart.v-split-panel .sp-chart { min-height: 0; padding: calc(var(--space-frame-y) * 1.6) var(--space-frame-x) var(--space-frame-y) calc(var(--space-gutter) * 1.5); }

.a-chart.v-takeaway {
  display: grid;
  grid-template-columns: minmax(0, 5fr) minmax(0, 7fr);
  grid-template-rows: minmax(0, 1fr);
  padding: calc(var(--space-frame-y) * 1.4) var(--space-frame-x) var(--space-frame-y);
  column-gap: calc(var(--space-gutter) * 2);
}
.a-chart.v-takeaway .ct-text { display: flex; flex-direction: column; gap: var(--space-gutter); overflow: hidden; }
.a-chart.v-takeaway .ct-source { margin-top: auto; }
.a-chart.v-takeaway .ct-chart { min-height: 0; display: grid; align-items: end; padding-top: var(--space-section); }
@container slide (aspect-ratio < 1) {
  .a-chart.v-takeaway { grid-template-columns: 1fr; grid-template-rows: auto minmax(0, 1fr); row-gap: var(--space-section); }
}

/* ---------- shared chart primitives (any VL restyles via .ch-*) ---------- */
.deck .ch { width: 100%; height: 100%; min-height: 0; position: relative; }
.deck .ch--empty { display: grid; place-items: center; border: var(--line-hair) dashed var(--color-line); }
.deck .ch--bar { display: grid; grid-template-columns: repeat(var(--n), minmax(0, 1fr)); gap: var(--space-tight); align-items: end; }
.deck .ch--bar .ch-col { display: grid; grid-template-rows: auto minmax(0, 1fr) auto; height: 100%; text-align: center; gap: 0.4em; }
.deck .ch--bar .ch-bar { align-self: end; height: var(--h); background: currentColor; opacity: 0.35; border-radius: 2px 2px 0 0; }
.deck .ch--bar .ch-val { align-self: end; }
.deck .ch--bar .is-hl .ch-bar { background: var(--color-emphasis); opacity: 1; }
.deck .ch--hbar { display: grid; align-content: center; gap: var(--space-gutter); }
.deck .ch--hbar .ch-row { display: grid; grid-template-columns: minmax(0, 2fr) minmax(0, 5fr) auto; align-items: center; gap: var(--space-gutter); }
.deck .ch--hbar .ch-track { height: 10px; background: color-mix(in srgb, currentColor 12%, transparent); border-radius: 999px; overflow: hidden; }
.deck .ch--hbar .ch-bar { display: block; height: 100%; width: var(--w); background: currentColor; opacity: 0.55; border-radius: inherit; }
.deck .ch--hbar .is-hl .ch-bar { background: var(--color-emphasis); opacity: 1; }
.deck .ch--area { display: grid; grid-template-rows: minmax(0, 1fr) auto; gap: var(--space-tight); }
.deck .ch--area .ch-plot { position: relative; min-height: 0; border-bottom: var(--line-hair) solid var(--color-line); }
.deck .ch--area svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.deck .ch--area .ch-line { fill: none; stroke: var(--color-emphasis); stroke-width: 2.5; }
.deck .ch--area .ch-fill-a { stop-color: var(--color-emphasis); stop-opacity: 0.45; }
.deck .ch--area .ch-fill-b { stop-color: var(--color-emphasis); stop-opacity: 0; }
.deck .ch--area .ch-dot { position: absolute; width: 14px; height: 14px; border-radius: 50%; background: var(--color-emphasis); transform: translate(-50%, -50%); box-shadow: 0 0 0 6px color-mix(in srgb, var(--color-emphasis) 25%, transparent); }
.deck .ch--area .ch-flag { position: absolute; transform: translate(-100%, -170%); white-space: nowrap; padding-right: 0.4em; }
.deck .ch--area .ch-x { display: flex; justify-content: space-between; opacity: 0.7; }

/* sign-off: a 2×2 checker of colour blocks (one holds a photo, one a starburst) beside a loud thank-you */
.a-closing.v-block-checker { display: grid; grid-template-columns: minmax(0, 44fr) minmax(0, 56fr); padding: 0; }
.a-closing.v-block-checker .ck-grid { display: grid; grid-template-columns: 1fr 1fr; grid-template-rows: 1fr 1fr; }
.a-closing.v-block-checker .ck-cell { position: relative; margin: 0; overflow: hidden; }
.a-closing.v-block-checker .ck-cell--a { background: var(--b1); }
.a-closing.v-block-checker .ck-cell--b { background: var(--b2); display: grid; place-items: center; --b-burst: var(--b1); }
.a-closing.v-block-checker .ck-cell--c { background: var(--b3); border-radius: 0 0 0 100%; }
.a-closing.v-block-checker .ck-photo :is(img, .ph) { width: 100%; height: 100%; object-fit: cover; display: block; }
