.a-closing.v-block-checker .ck-contact { align-self: flex-start; padding: 0.7em 1em; background: var(--b1); color: var(--color-ink-primary); }

.a-closing.v-giant-photo { display: grid; grid-template-columns: minmax(0, 7fr) minmax(0, 4fr); grid-template-rows: minmax(0, 1fr); }
.a-closing.v-giant-photo .gp-left { display: flex; flex-direction: column; gap: var(--space-gutter); padding: calc(var(--space-frame-y) * 1.2) var(--space-gutter) var(--space-frame-y) calc(var(--space-frame-x) * 0.4); overflow: hidden; }
.a-closing.v-giant-photo .gp-body { max-width: 16em; padding-left: calc(var(--space-frame-x) * 0.6); }
.a-closing.v-giant-photo .gp-left > .t-caption { padding-left: calc(var(--space-frame-x) * 0.6); }
.a-closing.v-giant-photo .gp-title { margin-top: auto; display: block; max-width: 100%; overflow: hidden; line-height: 0.86; }
.a-closing.v-giant-photo .gp-photo { position: relative; overflow: hidden; }
.a-closing.v-giant-photo .gp-photo :is(img, .ph) { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }

.a-closing.v-illo-center { display: grid; grid-template-rows: auto minmax(0, 1fr) auto; justify-items: center; padding: var(--space-frame-y) var(--space-frame-x) calc(var(--space-frame-y) * 0.6); text-align: center; row-gap: var(--space-tight); }
.a-closing.v-illo-center .cc-head { display: grid; gap: var(--space-tight); justify-items: center; max-width: 80%; }
.a-closing.v-illo-center .cc-art { width: 100%; }
.a-closing.v-illo-center .cc-art { position: relative; min-height: 0; }
.a-closing.v-illo-center .cc-art :is(img, .il-art) { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; }
.a-closing.v-illo-center .cc-art .il-art svg { width: 100%; height: 100%; display: block; }

.a-closing.v-loop-title { display: grid; grid-template-columns: minmax(0, 3fr) minmax(0, 3fr) minmax(0, 2fr); grid-template-rows: auto minmax(0, 1fr); column-gap: var(--space-gutter); row-gap: var(--space-gutter); padding: calc(var(--space-frame-y) * 2) var(--space-frame-x) var(--space-frame-y) calc(var(--space-frame-x) * 1.6); }
.a-closing.v-loop-title .lt-head { grid-column: 1 / 3; display: grid; }
.a-closing.v-loop-title .lt-sub { grid-column: 3; align-self: end; }
.a-closing.v-loop-title .lt-photo { grid-column: 1; grid-row: 2; aspect-ratio: 4 / 3; align-self: start; max-height: 100%; }
.a-closing.v-loop-title .lt-photo { position: relative; overflow: hidden; }
.a-closing.v-loop-title .lt-photo :is(img, .ph) { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.a-closing.v-loop-title .lt-note { grid-column: 2; grid-row: 2; max-width: 22em; }

/* sign-off: a small thank-you top-left, contact at the foot, the brand mark large and faint on the right */
.a-closing.v-quiet-sign { display: grid; grid-template-rows: minmax(0, 1fr) auto; padding: var(--space-frame-y) var(--space-frame-x); }
.a-closing.v-quiet-sign .qs-mark { position: absolute; right: -6%; top: 50%; width: 58%; aspect-ratio: 1; transform: translateY(-50%); opacity: 0.07; z-index: 0; }
.a-closing.v-quiet-sign .qs-head { position: relative; z-index: 1; display: grid; align-content: start; gap: 0.4em; max-width: 34%; }
.a-closing.v-quiet-sign .qs-body { color: var(--color-ink-secondary); }
.a-closing.v-quiet-sign .qs-contact { position: relative; z-index: 1; }

.a-closing.v-ring {
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  place-items: center;
  padding: var(--space-frame-y) var(--space-frame-x);
  text-align: center;
}
.a-closing.v-ring .cr-ring { position: absolute; z-index: 0; left: 50%; top: 50%; height: 104cqh; aspect-ratio: 1; transform: translate(-50%, -50%); }
