  grid-template-rows: minmax(0, 1fr);
  padding: calc(var(--space-frame-y) * 1.3) var(--space-frame-x) var(--space-frame-y);
  column-gap: calc(var(--space-gutter) * 1.5);
}
.a-comparison.v-tiers .ti-head { display: grid; align-content: start; gap: var(--space-gutter); }
