}
.a-comparison.v-tiers .ti-col {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: calc(var(--space-tight) * 0.8);
  padding: calc(var(--space-gutter) * 1.4) var(--space-gutter) var(--space-gutter);
  border: var(--line-hair) solid var(--color-line);
  border-radius: var(--radius-card);
  background: var(--color-surface-card, transparent);
  min-width: 0;
  overflow: hidden;
}
.a-comparison.v-tiers .is-emphasis { background: var(--color-emphasis); border-color: var(--color-emphasis); color: var(--color-ink-on-emphasis, #fff); }
.a-comparison.v-tiers .ti-tag {
  position: absolute;
  top: var(--space-tight);
  left: var(--space-gutter);
  padding: 0.2em 0.7em;
  border-radius: var(--radius-pill);
