.a-image.v-collage { display: grid; grid-template-rows: minmax(0, 1fr) auto; row-gap: var(--space-tight); padding: var(--space-frame-y) var(--space-frame-x); }
.a-image.v-collage .co-grid { display: grid; grid-template-columns: 1.3fr 1fr; grid-template-rows: 1fr 1fr; gap: var(--space-tight); margin-right: 6%; }
.a-image.v-collage .co-tile:first-child { grid-row: 1 / span 2; }
.a-image.v-collage .co-tile { position: relative; overflow: hidden; }
.a-image.v-collage .co-tile :is(img, .ph) { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.a-image.v-collage .co-caption { justify-self: end; }

.a-image.v-grid { display: grid; grid-template-columns: minmax(0, 6fr) minmax(0, 5fr); grid-template-rows: minmax(0, 1fr); column-gap: var(--space-gutter); padding: calc(var(--space-frame-y) * 0.6) var(--space-frame-x) var(--space-frame-y) calc(var(--space-frame-x) * 0.4); }
.a-image.v-grid .ig-left { display: flex; flex-direction: column; justify-content: space-between; overflow: hidden; }
.a-image.v-grid .ig-title { display: block; max-width: 100%; overflow: hidden; line-height: 0.86; }
.a-image.v-grid .ig-body { display: grid; gap: var(--space-tight); max-width: 24em; padding-left: calc(var(--space-frame-x) * 0.6); }
.a-image.v-grid .ig-grid { display: grid; grid-template-columns: 1fr 1fr; grid-auto-rows: minmax(0, 1fr); gap: var(--space-tight); }
.a-image.v-grid .ig-tile { position: relative; overflow: hidden; }
.a-image.v-grid .ig-tile :is(img, .ph) { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }

.a-image.v-pair-text { display: grid; grid-template-columns: minmax(0, 6fr) minmax(0, 5fr); grid-template-rows: minmax(0, 1fr); column-gap: calc(var(--space-gutter) * 2); padding: calc(var(--space-frame-y) * 1.4) var(--space-frame-x) var(--space-frame-y); }
.a-image.v-pair-text .pt-photos { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-tight); align-self: center; height: 62%; }
.a-image.v-pair-text .pt-tile { position: relative; overflow: hidden; }
.a-image.v-pair-text .pt-tile :is(img, .ph) { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.a-image.v-pair-text .pt-text { display: flex; flex-direction: column; justify-content: center; gap: var(--space-gutter); overflow: visible; }
.a-image.v-pair-text .pt-eyebrow { max-width: 16em; }
.a-image.v-pair-text .pt-body { display: grid; gap: var(--space-tight); max-width: 18em; }

.a-image.v-photos-arrow { display: grid; grid-template-columns: minmax(0, 6fr) minmax(0, 5fr); grid-template-rows: 40% auto minmax(0, 1fr); column-gap: var(--space-gutter); row-gap: var(--space-gutter); padding: var(--space-frame-y) var(--space-frame-x); }
.a-image.v-photos-arrow .pa-photos { grid-column: 1 / -1; display: grid; grid-template-columns: 1fr 1fr 0.9fr; gap: var(--space-tight); }
.a-image.v-photos-arrow .pa-tile { position: relative; overflow: hidden; }
.a-image.v-photos-arrow .pa-tile :is(img, .ph) { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.a-image.v-photos-arrow .pa-titlerow { grid-column: 1 / -1; display: flex; align-items: center; justify-content: flex-end; gap: var(--space-gutter); }
.a-image.v-photos-arrow .pa-arrow { width: 300px; height: 70px; }
.a-image.v-photos-arrow .pa-title { display: block; white-space: nowrap; }
.a-image.v-photos-arrow .pa-text { display: grid; gap: var(--space-gutter); align-content: start; max-width: 34em; overflow: hidden; }

.a-image.v-strip { display: grid; grid-template-rows: minmax(0, 1fr) 34%; padding: calc(var(--space-frame-y) * 1.2) 0 0 0; }
.a-image.v-strip .is-text { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 4fr) minmax(0, 3fr); align-content: center; column-gap: var(--space-gutter); padding: 0 var(--space-frame-x) var(--space-gutter); overflow: hidden; }
