.a-metric.v-glass-cards .gc-value { display: block; width: 100%; overflow: hidden; margin-top: var(--space-section); }
.a-metric.v-glass-cards .gc-chip { align-self: flex-start; padding: 0.25em 0.6em; background: color-mix(in srgb, currentColor 14%, transparent); }
.a-metric.v-glass-cards .gc-note { opacity: 0.7; }
.a-metric.v-glass-cards .is-emphasis { background: var(--color-surface-highlight, var(--color-ink-on-inverse)); color: var(--color-ink-on-highlight, var(--color-ground-inverse)); border-color: transparent; }

.a-metric.v-hero-number {
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
