.a-metric.v-nested-circles .nc-tag { align-self: flex-start; }
/* circles sit on one shared bottom point; sizes are fixed steps so labels always get a band */
.a-metric.v-nested-circles .nc-items { position: relative; container-type: size; }
.a-metric.v-nested-circles .nc-item {
  --d: min(100cqw, 100cqh);
  --f: 1;
  position: absolute;
  left: 50%;
  bottom: 0;
  width: calc(var(--d) * var(--f));
  aspect-ratio: 1;
  transform: translateX(-50%);
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: calc(var(--space-tight) * 0.4);
  /* padding from the circle's own diameter (a % would resolve against the whole diagram) */
  padding: calc(var(--d) * 0.035) calc(var(--d) * var(--f) * 0.17) 0;
  text-align: center;
  background: color-mix(in srgb, currentColor 6%, transparent);
}
.a-metric.v-nested-circles [data-count="2"] .nc-item:nth-child(2) { --f: 0.6; }
.a-metric.v-nested-circles [data-count="3"] .nc-item:nth-child(2) { --f: 0.7; }
.a-metric.v-nested-circles [data-count="3"] .nc-item:nth-child(3) { --f: 0.42; }
.a-metric.v-nested-circles [data-count="4"] .nc-item:nth-child(2) { --f: 0.77; }
.a-metric.v-nested-circles [data-count="4"] .nc-item:nth-child(3) { --f: 0.55; }
.a-metric.v-nested-circles [data-count="4"] .nc-item:nth-child(4) { --f: 0.34; }
.a-metric.v-nested-circles .nc-item:last-child { justify-content: center; padding-top: 0; }
.a-metric.v-nested-circles .nc-value { display: block; width: 100%; overflow: hidden; }
.a-metric.v-nested-circles .is-emphasis { box-shadow: inset 0 0 0 var(--line-rule) var(--color-emphasis); }

.a-metric.v-poster-figure { display: grid; grid-template-rows: auto minmax(0, 1fr) auto; padding: calc(var(--space-frame-y) * 1.2) var(--space-frame-x) var(--space-frame-y); row-gap: var(--space-gutter); }
.a-metric.v-poster-figure .pf-head { display: grid; gap: var(--space-tight); max-width: 46%; }
.a-metric.v-poster-figure .pf-items { display: grid; align-items: end; overflow: hidden; }
.a-metric.v-poster-figure .pf-item { display: grid; grid-template-columns: minmax(0, auto) minmax(0, 18em); align-items: end; column-gap: var(--space-gutter); }
.a-metric.v-poster-figure .pf-value { display: block; min-width: 0; overflow: hidden; line-height: 0.82; font-size: calc(var(--t-display-0-size) * 1.5); color: var(--color-emphasis); }
.a-metric.v-poster-figure .pf-label { display: grid; gap: 0.3em; padding-bottom: 1.2em; }

.a-metric.v-ring-gauges {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  padding: calc(var(--space-frame-y) * 1.4) var(--space-frame-x) var(--space-frame-y);
  row-gap: var(--space-section);
}
.a-metric.v-ring-gauges .rg-head { display: grid; gap: var(--space-tight); max-width: 60%; }
.a-metric.v-ring-gauges .rg-items {
  display: grid;
  grid-template-columns: repeat(var(--item-count), minmax(0, 1fr));
  gap: var(--space-gutter);
  overflow: hidden;
}
.a-metric.v-ring-gauges .rg-item { container-type: size; display: grid; place-items: center; min-height: 0; }
.a-metric.v-ring-gauges .rg-gauge { position: relative; width: min(100cqw, 100cqh); aspect-ratio: 1; }
/* dotted rings: 64 round dots; the fill ring is clipped to the percentage with a conic mask */
.a-metric.v-ring-gauges .rg-ring { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.a-metric.v-ring-gauges .rg-ring circle { fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-dasharray: 0 1; }
.a-metric.v-ring-gauges .rg-ring--track { opacity: 0.28; }
.a-metric.v-ring-gauges .rg-ring--fill {
  color: var(--color-emphasis);
  -webkit-mask-image: conic-gradient(#000 calc(var(--pct) * 3.6deg), transparent 0);
  mask-image: conic-gradient(#000 calc(var(--pct) * 3.6deg), transparent 0);
}
.a-metric.v-ring-gauges .rg-core {
  position: absolute;
  inset: 11%;
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: calc(var(--space-tight) * 0.6);
  padding: 0 12%;
  text-align: center;
  background: var(--color-surface-card, transparent);
  border: var(--line-hair) solid var(--color-line);
}
.a-metric.v-ring-gauges .rg-value { display: block; width: 100%; overflow: hidden; }

.a-metric.v-row {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  padding: calc(var(--space-frame-y) * 1.5) var(--space-frame-x) var(--space-frame-y);
  gap: var(--space-section);
}
.a-metric.v-row .m-head { display: grid; gap: var(--space-tight); max-width: 70%; }
.a-metric.v-row .m-items {
  display: grid;
  grid-template-columns: repeat(var(--item-count), minmax(0, 1fr));
  gap: var(--space-gutter);
  align-items: end;
  overflow: hidden;
}
.a-metric.v-row .m-item {
  display: grid;
  gap: var(--space-tight);
  align-content: end;
  padding-top: var(--space-tight);
  border-top: var(--line-rule) solid var(--color-line);
  min-width: 0;
}
.a-metric.v-row .m-value { display: block; min-width: 0; overflow: hidden; }
.a-metric.v-row .is-emphasis .m-value { color: var(--color-emphasis); }
.a-metric.v-row .is-emphasis { border-top-color: var(--color-emphasis); }

.a-people.v-portrait-row { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 6fr); grid-template-rows: minmax(0, 1fr); column-gap: calc(var(--space-gutter) * 2); padding: calc(var(--space-frame-y) * 1.4) var(--space-frame-x) var(--space-frame-y); }
.a-people.v-portrait-row .pr-left { display: flex; flex-direction: column; justify-content: space-between; overflow: visible; }
.a-people.v-portrait-row .pr-titlerow { display: flex; align-items: flex-start; gap: var(--space-gutter); }
