.a-people.v-portrait-row .pr-copy { display: grid; gap: var(--space-gutter); max-width: 22em; }
.a-people.v-portrait-row .pr-people { display: grid; grid-template-columns: repeat(var(--item-count), minmax(0, 1fr)); gap: var(--space-gutter); align-self: center; }
.a-people.v-portrait-row .pr-person { display: grid; gap: 0.3em; align-content: start; }
.a-people.v-portrait-row .pr-photo { aspect-ratio: 3 / 4; margin-bottom: var(--space-tight); }
.a-people.v-portrait-row .pr-photo { position: relative; overflow: hidden; }
.a-people.v-portrait-row .pr-photo :is(img, .ph) { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.a-people.v-portrait-row .pr-bio { text-transform: none; letter-spacing: 0; opacity: 0.8; }

.a-quote.v-centered-badge {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  justify-items: center;
  padding: var(--space-frame-y) var(--space-frame-x);
  text-align: center;
  gap: var(--space-gutter);
}
.a-quote.v-centered-badge .qb-top { display: grid; justify-items: center; gap: var(--space-tight); min-height: 1em; }
/* content-sized pill: never a fixed circle, so "+2wk"-style values cannot wrap */
.a-quote.v-centered-badge .qb-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 2.6em;
  height: 2.6em;
  padding: 0 0.9em;
  border-radius: var(--radius-pill);
  border: var(--line-rule) solid currentColor;
  white-space: nowrap;
}
.a-quote.v-centered-badge .qb-main { display: grid; place-items: center; max-width: 64%; max-height: 100%; overflow: hidden; }
@container slide (aspect-ratio < 1) {
  .a-quote.v-centered-badge .qb-main { max-width: 100%; }
}

.a-quote.v-corner-question {
  display: grid;
  grid-template-rows: minmax(0, 1fr) 22%;
  padding: var(--space-frame-y) var(--space-frame-x) 0;
}
.a-quote.v-corner-question .cq-main { display: grid; align-content: start; gap: var(--space-gutter); max-width: 62%; overflow: hidden; }
.a-quote.v-corner-question .cq-strip { margin: 0 calc(var(--space-frame-x) * -1); }
@container slide (aspect-ratio < 1) {
  .a-quote.v-corner-question .cq-main { max-width: 100%; }
}

.a-quote.v-quote-photo { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); grid-template-rows: minmax(0, 1fr); }
.a-quote.v-quote-photo .qp-text { display: flex; flex-direction: column; gap: var(--space-section); padding: calc(var(--space-frame-y) * 1.2) calc(var(--space-gutter) * 2) var(--space-frame-y) var(--space-frame-x); overflow: hidden; }
.a-quote.v-quote-photo .qp-quote { max-width: 24em; }
.a-quote.v-quote-photo .qp-note { max-width: 22em; }
.a-quote.v-quote-photo .qp-photo { position: relative; overflow: hidden; color: var(--color-ink-on-inverse); }
.a-quote.v-quote-photo .qp-photo :is(img, .ph) { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.a-quote.v-quote-photo .qp-attr { position: absolute; left: var(--space-gutter); right: var(--space-gutter); bottom: var(--space-gutter); padding-top: var(--space-tight); border-top: var(--line-hair) solid currentColor; }

/* a single light quote centred in the panel, attribution set small beneath */
.a-quote.v-soft-center { display: grid; place-items: center; padding: var(--space-frame-y) calc(var(--space-frame-x) * 2.2); text-align: center; }
.a-quote.v-soft-center .qs-main { display: grid; justify-items: center; gap: var(--space-gutter); margin: 0; max-width: 960px; }

.a-quote.v-stat-illo { display: grid; grid-template-columns: minmax(0, 4fr) minmax(0, 6fr); grid-template-rows: minmax(0, 1fr); }
.a-quote.v-stat-illo .st-left { position: relative; display: flex; flex-direction: column; justify-content: center; align-items: center; gap: var(--space-gutter); padding: var(--space-frame-y) var(--space-frame-x); text-align: center; overflow: hidden; }
.a-quote.v-stat-illo .st-left::before { content: ""; position: absolute; top: 0; left: 50%; height: 26%; border-left: var(--line-hair) solid currentColor; }
.a-quote.v-stat-illo .st-art { background: var(--illo-panel, var(--color-ground-accent-0)); }
.a-quote.v-stat-illo .st-art { position: relative; min-height: 0; }
.a-quote.v-stat-illo .st-art :is(img, .il-art) { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; }
.a-quote.v-stat-illo .st-art .il-art svg { width: 100%; height: 100%; display: block; }
.a-quote.v-stat-illo .st-art :is(img, .il-art) { inset: 8% 6% 0; }

/* break slide: a giant title with a starburst on its shoulder, a colour band below, a zigzag strip on the right */
.a-section.v-burst { display: grid; grid-template-columns: minmax(0, 1fr) 140px; grid-template-rows: minmax(0, 1fr) 30%; padding: 0; }
.a-section.v-burst .sb-main { position: relative; grid-column: 1; grid-row: 1; display: flex; flex-direction: column; justify-content: center; gap: var(--space-tight); padding: var(--space-frame-y) var(--space-gutter) var(--space-gutter) var(--space-frame-x); overflow: hidden; z-index: 1; }
.a-section.v-burst .sb-title { position: relative; z-index: 1; overflow-wrap: normal; hyphens: manual; }
.a-section.v-burst .sb-burst { position: absolute; left: calc(var(--space-frame-x) * 0.35); top: 12%; width: 220px; height: 220px; z-index: 0; }
.a-section.v-burst .sb-band { grid-column: 1; grid-row: 2; margin: 0 45% 0 0; background: var(--b1); overflow: hidden; }
.a-section.v-burst .sb-band img { width: 100%; height: 100%; object-fit: cover; display: block; }
.a-section.v-burst .sb-kicker { grid-column: 1; grid-row: 2; justify-self: end; align-self: end; width: 40%; margin: 0 var(--space-gutter) var(--space-frame-y) 0; }
.a-section.v-burst .sb-zig { grid-column: 2; grid-row: 1 / span 2; margin: var(--space-frame-y) var(--space-gutter) var(--space-frame-y) 0; }

.a-section.v-centered {
  display: grid;
  grid-template-rows: minmax(0, 1fr);
  place-items: center;
  padding: var(--space-frame-y) var(--space-frame-x);
  text-align: center;
}
.a-section.v-centered .sc-main {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-tight);
  max-width: 70%;
  max-height: 100%;
  overflow: hidden;
}
.a-section.v-centered .sc-kicker { max-width: 34em; margin-top: var(--space-tight); }
@container slide (aspect-ratio < 1) {
  .a-section.v-centered .sc-main { max-width: 100%; }
}

/* a giant numeral runs off the right edge behind a bottom-left title; VLs decide how it fades */
.a-section.v-ghost-number {
