  grid-template-rows: minmax(0, 1fr);
  padding: var(--space-frame-y) var(--space-frame-x);
}
.a-section.v-ghost-number .gn-num {
  position: absolute;
  z-index: 0;
  right: -6cqh;
  top: 50%;
  transform: translateY(-50%);
  font-family: var(--font-display);
  font-size: 128cqh;
