  position: relative;
  z-index: 1;
  align-self: end;
  display: grid;
  gap: var(--space-tight);
  max-width: 55%;
  max-height: 100%;
  overflow: hidden;
}

.a-section.v-illo-chapter { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); padding: calc(var(--space-frame-y) * 1.4) var(--space-frame-x) 0; column-gap: var(--space-gutter); }
.a-section.v-illo-chapter .ch-tab { position: absolute; top: 0; left: 72%; padding: 0.15em 0.55em 0.25em; background: currentColor; border-radius: 0 0 8px 8px; }
.a-section.v-illo-chapter .ch-tab { color: var(--slide-ink); }
.a-section.v-illo-chapter .ch-tab { -webkit-text-fill-color: var(--slide-bg); }
.a-section.v-illo-chapter .ch-rule { position: absolute; top: 0; bottom: 0; left: 50%; border-left: var(--line-hair) solid currentColor; }
