.a-timeline.v-schedule-photo .sch-items { margin-top: auto; display: grid; grid-template-columns: repeat(var(--item-count), minmax(0, 1fr)); gap: var(--space-gutter); padding-left: calc(var(--space-frame-x) * 0.6); }
.a-timeline.v-schedule-photo .sch-item { display: grid; align-content: start; gap: 0.35em; padding-top: var(--space-tight); border-top: var(--line-hair) solid var(--color-line); }
.a-timeline.v-schedule-photo .sch-item.is-emphasis { border-top: var(--line-rule) solid var(--color-emphasis); }
.a-timeline.v-schedule-photo .sch-text { opacity: 0.65; }
.a-timeline.v-schedule-photo .sch-photo { position: relative; overflow: hidden; }
.a-timeline.v-schedule-photo .sch-photo :is(img, .ph) { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }

.a-timeline.v-stages-photo { display: grid; grid-template-columns: minmax(0, 6fr) minmax(0, 5fr); grid-template-rows: auto minmax(0, 1fr); column-gap: calc(var(--space-gutter) * 2); row-gap: var(--space-gutter); padding: calc(var(--space-frame-y) * 1.2) var(--space-frame-x) var(--space-frame-y); }
.a-timeline.v-stages-photo .sg-head { display: grid; gap: var(--space-gutter); align-content: start; }
.a-timeline.v-stages-photo .pr-titlerow { display: flex; align-items: flex-end; gap: var(--space-gutter); }
.a-timeline.v-stages-photo .sg-arrow { width: 220px; height: 60px; flex-shrink: 0; }
.a-timeline.v-stages-photo .sg-items { grid-row: 1 / span 2; grid-column: 2; display: grid; align-content: start; gap: var(--space-section); overflow: hidden; }
.a-timeline.v-stages-photo .sg-item { display: grid; gap: 0.4em; }
.a-timeline.v-stages-photo .sg-label { font-weight: 700; }
.a-timeline.v-stages-photo .sg-photo { grid-column: 1; grid-row: 2; }
.a-timeline.v-stages-photo .sg-photo { position: relative; overflow: hidden; }
.a-timeline.v-stages-photo .sg-photo :is(img, .ph) { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }

/* title runs bottom-to-top in its own column */
.a-timeline.v-vertical-title { display: grid; grid-template-columns: minmax(0, 5fr) auto minmax(0, 5fr); grid-template-rows: minmax(0, 1fr); column-gap: calc(var(--space-gutter) * 1.5); padding: var(--space-frame-y) var(--space-frame-x); }
.a-timeline.v-vertical-title .vt-left { display: grid; align-content: start; gap: var(--space-gutter); max-width: 26em; }
.a-timeline.v-vertical-title .vt-bar { height: 22px; width: 70%; }
.a-timeline.v-vertical-title .vt-title-col { display: flex; align-items: flex-start; justify-content: center; }
.a-timeline.v-vertical-title .vt-title { writing-mode: vertical-rl; transform: rotate(180deg); white-space: nowrap; }
.a-timeline.v-vertical-title .vt-items { display: grid; align-content: start; gap: var(--space-tight); overflow: hidden; }
.a-timeline.v-vertical-title .vt-item { display: grid; gap: 0.15em; }
.a-timeline.v-vertical-title .vt-label { font-weight: 500; }
.a-timeline.v-vertical-title .vt-text { text-transform: none; letter-spacing: 0; opacity: 0.8; }

.a-timeline.v-wave {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  padding: calc(var(--space-frame-y) * 1.3) var(--space-frame-x) var(--space-frame-y);
  row-gap: var(--space-gutter);
}
.a-timeline.v-wave .tw-head { display: grid; gap: var(--space-tight); }
.a-timeline.v-wave .tw-range {
  display: flex;
  align-items: baseline;
  gap: var(--space-gutter);
  padding-bottom: var(--space-tight);
  border-bottom: var(--line-hair) solid var(--color-line);
}
.a-timeline.v-wave .tw-end { margin-left: auto; }
/* every item spans three shared rows: text above / track / text below. Odd items speak above, even below. */
.a-timeline.v-wave .tw-items {
  display: grid;
  grid-template-columns: repeat(var(--item-count), minmax(0, 1fr));
  grid-template-rows: minmax(0, 1fr) 22% minmax(0, 1fr);
  overflow: hidden;
}
.a-timeline.v-wave .tw-item { grid-row: 1 / 4; display: grid; grid-template-rows: subgrid; min-width: 0; }
.a-timeline.v-wave .tw-text {
  grid-row: 1;
  align-self: end;
  display: grid;
  justify-items: start;
  gap: calc(var(--space-tight) * 0.6);
  padding: 0 var(--space-gutter) var(--space-gutter) 0;
  min-width: 0;
}
.a-timeline.v-wave .tw-item:nth-child(even) .tw-text { grid-row: 3; align-self: start; padding: var(--space-gutter) var(--space-gutter) 0 0; }
.a-timeline.v-wave .tw-pill {
  display: inline-flex;
  padding: 0.5em 1.1em;
  border-radius: var(--radius-pill);
  border: var(--line-hair) solid var(--color-line);
