  max-width: 100%;
  overflow: hidden;
  margin-bottom: var(--space-tight);
}
.a-timeline.v-wave .tw-points { display: grid; gap: 0.3em; padding-left: 1em; list-style: disc; }
.a-timeline.v-wave .tw-seg { grid-row: 2; position: relative; }
/* fallback track when the VL draws no segment ornament */
