.a-timeline.v-wave .tw-lens { position: absolute; inset: 0; }
.a-timeline.v-wave .tw-node {
  position: absolute;
  left: 0;
  top: 50%;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  background: var(--slide-bg);
  border: var(--line-hair) solid currentColor;
  z-index: 1;
}
.a-timeline.v-wave .is-emphasis .tw-node { background: var(--color-emphasis); border-color: var(--color-emphasis); }
.a-timeline.v-wave .tw-stem { position: absolute; left: 0; bottom: 50%; height: 50%; border-left: var(--line-hair) solid var(--color-line); }
.a-timeline.v-wave .tw-item:nth-child(even) .tw-stem { top: 50%; bottom: auto; }

/* cover: a colour-block collage with a framed photo on the left, a loud title block on the right */
.a-title.v-block-collage { display: grid; grid-template-columns: minmax(0, 42fr) minmax(0, 58fr); padding: 0; }
.a-title.v-block-collage .bc-art { position: relative; overflow: hidden; }
.a-title.v-block-collage .bc-block { position: absolute; }
.a-title.v-block-collage .bc-block--a { left: 0; top: 0; width: 64%; height: 58%; background: var(--b1); }
.a-title.v-block-collage .bc-block--b { right: 0; bottom: 0; width: 44%; aspect-ratio: 1; border-radius: 100% 0 0 0; background: var(--b2); }
.a-title.v-block-collage .bc-block--c { left: 8%; bottom: 10%; width: 15%; aspect-ratio: 1; border-radius: 50%; background: var(--b3); z-index: 2; }
.a-title.v-block-collage .bc-photo { position: absolute; left: 22%; top: 14%; width: 56%; height: 70%; margin: 0; overflow: hidden; z-index: 1; }
.a-title.v-block-collage .bc-photo :is(img, .ph) { width: 100%; height: 100%; object-fit: cover; display: block; }
.a-title.v-block-collage .bc-main { position: relative; z-index: 1; display: flex; flex-direction: column; justify-content: center; gap: var(--space-gutter); padding: var(--space-frame-y) var(--space-frame-x) var(--space-frame-y) calc(var(--space-frame-x) * 0.8); overflow: hidden; }
