.a-title.v-block-collage .bc-meta { display: flex; flex-wrap: wrap; gap: 0.4em var(--space-gutter); margin-top: calc(var(--space-gutter) * 0.5); }
.a-title.v-block-collage .bc-burst { position: absolute; left: calc(42% * 0.78 - 80px); top: calc(14% * 0.7 - 20px); width: 160px; height: 160px; z-index: 2; }

.a-title.v-centered {
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto auto;
  justify-items: center;
  padding: var(--space-frame-y) var(--space-frame-x);
  text-align: center;
}
.a-title.v-centered .tc-main {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--space-tight);
  max-width: 72%;
  max-height: 100%;
  overflow: hidden;
}
.a-title.v-centered .tc-subtitle { margin-top: calc(var(--space-tight) * 0.5); }
@container slide (aspect-ratio < 1) {
  .a-title.v-centered .tc-main { max-width: 100%; }
}

.a-title.v-full-bleed-photo { display: grid; grid-template-rows: minmax(0, 1fr) auto; padding: var(--space-frame-y) var(--space-frame-x); color: var(--color-ink-on-inverse); }
.a-title.v-full-bleed-photo .fb-photo { position: absolute; inset: 0; z-index: 0; }
.a-title.v-full-bleed-photo .fb-photo :is(img, .ph) { width: 100%; height: 100%; object-fit: cover; display: block; }
.a-title.v-full-bleed-photo > :not(.fb-photo):not([data-decor]) { position: relative; z-index: 1; }
.a-title.v-full-bleed-photo .fb-main { align-self: center; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 0.42fr); align-items: end; gap: var(--space-gutter); overflow: hidden; }
.a-title.v-full-bleed-photo .fb-subtitle { max-width: 22em; }
.a-title.v-full-bleed-photo .fb-meta { display: flex; justify-content: space-between; gap: var(--space-gutter); padding-top: var(--space-tight); border-top: var(--line-hair) solid currentColor; margin-left: 30%; }

.a-title.v-giant-word { display: grid; grid-template-rows: 44% auto minmax(0, 1fr) auto; padding: calc(var(--space-frame-y) * 0.6) var(--space-frame-x) var(--space-frame-y); row-gap: var(--space-gutter); }
.a-title.v-giant-word .gw-band { position: relative; overflow: hidden; }
.a-title.v-giant-word .gw-band :is(img, .ph) { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.a-title.v-giant-word .gw-meta { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-gutter); max-width: 60%; }
.a-title.v-giant-word .gw-word { display: flex; align-items: flex-end; overflow: hidden; }
.a-title.v-giant-word .gw-title { display: block; max-width: 100%; overflow: hidden; line-height: 0.82; }
.a-title.v-giant-word .gw-foot { display: flex; gap: calc(var(--space-gutter) * 4); }

.a-title.v-illo-cover { display: grid; grid-template-rows: auto minmax(0, 1fr) auto; padding: calc(var(--space-frame-y) * 0.6) var(--space-frame-x); }
.a-title.v-illo-cover .ic-art { position: absolute; inset: 2% 4% 6%; z-index: 0; }
.a-title.v-illo-cover .ic-art :is(img, .il-art) { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; }
.a-title.v-illo-cover .ic-art .il-art svg { width: 100%; height: 100%; display: block; }
.a-title.v-illo-cover > :not(.ic-art):not([data-decor]) { position: relative; z-index: 1; }
/* the cast stands in the side gutters, so the title keeps to the middle and shrinks rather than running under them */
.a-title.v-illo-cover .ic-main { display: grid; place-items: center; text-align: center; padding: 0 25%; overflow: hidden; }
.a-title.v-illo-cover .ic-foot { display: flex; justify-content: center; gap: var(--space-gutter); align-items: baseline; }
.a-title.v-illo-cover .ic-eyebrow { grid-row: 1; }
